import React, { useState, useEffect } from "react";
import { Container, ContentWithPaddingXl } from "components/misc/Layouts";
import { SectionHeading } from "components/misc/Headings";
import { PrimaryButton, SecondaryButton } from "components/misc/Buttons";
import { ReactComponent as UsersIcon } from "images/team-illustration.svg";
import { ReactComponent as ReferralIcon } from "images/celebration-icon.svg";
import { ReactComponent as StatsIcon } from "images/stats-illustration.svg";
import { ReactComponent as SettingsIcon } from "images/settings-icon.svg";
import styled from "styled-components";

const AdminContainer = styled.div`
  min-height: 100vh;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
`;

const AdminCard = styled.div`
  background: white;
  border-radius: 15px;
  padding: 2rem;
  margin-bottom: 2rem;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s ease;

  &:hover {
    transform: translateY(-5px);
  }
`;

const StatsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
`;

const StatCard = styled.div`
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  padding: 1.5rem;
  border-radius: 15px;
  text-align: center;
`;

const StatNumber = styled.div`
  font-size: 2.5rem;
  font-weight: bold;
  margin-bottom: 0.5rem;
`;

const StatLabel = styled.div`
  font-size: 1rem;
  opacity: 0.9;
`;

const TableContainer = styled.div`
  overflow-x: auto;
  margin-top: 1rem;
`;

const Table = styled.table`
  width: 100%;
  border-collapse: collapse;
  background: white;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
`;

const Th = styled.th`
  background: #f8f9fa;
  padding: 1rem;
  text-align: left;
  font-weight: 600;
  border-bottom: 2px solid #e9ecef;
`;

const Td = styled.td`
  padding: 1rem;
  border-bottom: 1px solid #e9ecef;
`;

const Tr = styled.tr`
  &:hover {
    background: #f8f9fa;
  }
`;

const SearchInput = styled.input`
  width: 100%;
  padding: 0.75rem;
  border: 2px solid #e9ecef;
  border-radius: 8px;
  margin-bottom: 1rem;
  font-size: 1rem;

  &:focus {
    outline: none;
    border-color: #667eea;
  }
`;

const TabContainer = styled.div`
  display: flex;
  margin-bottom: 2rem;
  border-bottom: 2px solid #e9ecef;
`;

const Tab = styled.button`
  padding: 1rem 2rem;
  background: ${props => props.active ? '#667eea' : 'transparent'};
  color: ${props => props.active ? 'white' : '#6c757d'};
  border: none;
  border-radius: 8px 8px 0 0;
  cursor: pointer;
  font-weight: 600;
  transition: all 0.2s ease;

  &:hover {
    background: ${props => props.active ? '#667eea' : '#f8f9fa'};
  }
`;

const ActionButton = styled.button`
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  font-size: 0.9rem;
  margin: 0 0.25rem;
  transition: all 0.2s ease;

  &.edit {
    background: #28a745;
    color: white;
    &:hover { background: #218838; }
  }

  &.delete {
    background: #dc3545;
    color: white;
    &:hover { background: #c82333; }
  }

  &.ban {
    background: #ffc107;
    color: #212529;
    &:hover { background: #e0a800; }
  }
`;

const AdminPanel = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [referrals, setReferrals] = useState([]);
  const [stats, setStats] = useState({
    totalUsers: 0,
    totalReferrals: 0,
    activeUsers: 0,
    pendingReferrals: 0
  });
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAdminData();
  }, []);

  const fetchAdminData = async () => {
    try {
      const token = localStorage.getItem('jwt');
      if (!token) {
        alert('Please login as admin');
        return;
      }

      const [usersRes, statsRes] = await Promise.all([
        fetch('/api/admin/users', {
          headers: { Authorization: `Bearer ${token}` }
        }),
        fetch('/api/admin/stats', {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);

      if (usersRes.ok) {
        const usersData = await usersRes.json();
        setUsers(usersData);
      }

      if (statsRes.ok) {
        const statsData = await statsRes.json();
        setStats(statsData);
      }
    } catch (error) {
      console.error('Error fetching admin data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleUserAction = async (userId, action) => {
    try {
      const token = localStorage.getItem('jwt');
      const response = await fetch(`/api/admin/users/${userId}/${action}`, {
        method: 'PUT',
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.ok) {
        fetchAdminData(); // Refresh data
        alert(`User ${action} successful`);
      } else {
        alert(`Failed to ${action} user`);
      }
    } catch (error) {
      console.error(`Error ${action}ing user:`, error);
      alert(`Error ${action}ing user`);
    }
  };

  const filteredUsers = users.filter(user =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.referralCode.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) {
    return (
      <AdminContainer>
        <Container>
          <ContentWithPaddingXl>
            <div style={{ textAlign: 'center', padding: '4rem' }}>
              <div>Loading admin panel...</div>
            </div>
          </ContentWithPaddingXl>
        </Container>
      </AdminContainer>
    );
  }

  return (
    <AdminContainer>
      <Container>
        <ContentWithPaddingXl>
          <SectionHeading style={{ textAlign: 'center', color: 'white', marginBottom: '3rem' }}>
            Admin Panel
          </SectionHeading>

          <TabContainer>
            <Tab 
              active={activeTab === 'dashboard'} 
              onClick={() => setActiveTab('dashboard')}
            >
              Dashboard
            </Tab>
            <Tab 
              active={activeTab === 'users'} 
              onClick={() => setActiveTab('users')}
            >
              Users
            </Tab>
            <Tab 
              active={activeTab === 'referrals'} 
              onClick={() => setActiveTab('referrals')}
            >
              Referrals
            </Tab>
            <Tab 
              active={activeTab === 'settings'} 
              onClick={() => setActiveTab('settings')}
            >
              Settings
            </Tab>
          </TabContainer>

          {activeTab === 'dashboard' && (
            <AdminCard>
              <h2 style={{ marginBottom: '2rem', color: '#333' }}>System Overview</h2>
              <StatsGrid>
                <StatCard>
                  <StatNumber>{stats.totalUsers}</StatNumber>
                  <StatLabel>Total Users</StatLabel>
                </StatCard>
                <StatCard>
                  <StatNumber>{stats.totalReferrals}</StatNumber>
                  <StatLabel>Total Referrals</StatLabel>
                </StatCard>
                <StatCard>
                  <StatNumber>{stats.activeUsers}</StatNumber>
                  <StatLabel>Active Users</StatLabel>
                </StatCard>
                <StatCard>
                  <StatNumber>{stats.pendingReferrals}</StatNumber>
                  <StatLabel>Pending Referrals</StatLabel>
                </StatCard>
              </StatsGrid>
            </AdminCard>
          )}

          {activeTab === 'users' && (
            <AdminCard>
              <h2 style={{ marginBottom: '2rem', color: '#333' }}>User Management</h2>
              <SearchInput
                type="text"
                placeholder="Search users by name, email, or referral code..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
              <TableContainer>
                <Table>
                  <thead>
                    <tr>
                      <Th>Name</Th>
                      <Th>Email</Th>
                      <Th>Referral Code</Th>
                      <Th>Referrals</Th>
                      <Th>Referred By</Th>
                      <Th>Joined</Th>
                      <Th>Actions</Th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredUsers.map(user => (
                      <Tr key={user._id}>
                        <Td>{user.name}</Td>
                        <Td>{user.email}</Td>
                        <Td>{user.referralCode}</Td>
                        <Td>{user.referrals}</Td>
                        <Td>{user.referredBy || 'None'}</Td>
                        <Td>{new Date(user.createdAt).toLocaleDateString()}</Td>
                        <Td>
                          <ActionButton 
                            className="edit"
                            onClick={() => handleUserAction(user._id, 'edit')}
                          >
                            Edit
                          </ActionButton>
                          <ActionButton 
                            className="ban"
                            onClick={() => handleUserAction(user._id, 'ban')}
                          >
                            Ban
                          </ActionButton>
                          <ActionButton 
                            className="delete"
                            onClick={() => handleUserAction(user._id, 'delete')}
                          >
                            Delete
                          </ActionButton>
                        </Td>
                      </Tr>
                    ))}
                  </tbody>
                </Table>
              </TableContainer>
            </AdminCard>
          )}

          {activeTab === 'referrals' && (
            <AdminCard>
              <h2 style={{ marginBottom: '2rem', color: '#333' }}>Referral Management</h2>
              <p>Referral analytics and management tools will be displayed here.</p>
            </AdminCard>
          )}

          {activeTab === 'settings' && (
            <AdminCard>
              <h2 style={{ marginBottom: '2rem', color: '#333' }}>System Settings</h2>
              <p>System configuration and settings will be displayed here.</p>
            </AdminCard>
          )}
        </ContentWithPaddingXl>
      </Container>
    </AdminContainer>
  );
};

export default AdminPanel;
